import{_ as e,o as t,c as s,a6 as p}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"摄影、场景与空间表现","description":"","frontmatter":{"id":"space","title":"摄影、场景与空间表现","chapter":"07","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":33,"content_kind":"任务入门"},"headers":[],"relativePath":"people-space/space.md","filePath":"people-space/space.md"}'),r={name:"people-space/space.md"};function o(i,a,n,c,l,d){return t(),s("div",null,[...a[0]||(a[0]=[p(`<h1 id="摄影、场景与空间-保持透视再换环境" tabindex="-1">摄影、场景与空间，保持透视再换环境 <a class="header-anchor" href="#摄影、场景与空间-保持透视再换环境" aria-label="Permalink to &quot;摄影、场景与空间，保持透视再换环境&quot;">​</a></h1><p>本节以真实椅子放进书房为练习，交付空场景、商品合成和尺寸说明。商品使用真实照片，空间概念另标推演。设计效果图不能证明房间结构、承重或实际安装条件。</p><h2 id="_1-先看照片视角" tabindex="-1">1. 先看照片视角 <a class="header-anchor" href="#_1-先看照片视角" aria-label="Permalink to &quot;1. 先看照片视角&quot;">​</a></h2><p>椅子是平视、俯视还是低角度，地面方向与阴影怎样？选同类视角背景，商品才能站在地上。椅子宽高来自真实记录，桌子与房间只是场景元素，避免误导实际尺寸关系。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成一张明亮书房空背景，不生成椅子。浅木地板、奶油白墙面，左侧窗户柔和自然光，右侧简洁书桌。镜头为正常视角，接近上传商品照片的高度，不使用广角夸张透视。</span></span>
<span class="line"><span>中央偏右留一片无遮挡地面供真实椅子合成，背景简洁，前景不要挡主体。不要文字、标识、水印、人物或虚构商品。</span></span></code></pre></div><h2 id="_2-合成时先解决-落地" tabindex="-1">2. 合成时先解决“落地” <a class="header-anchor" href="#_2-合成时先解决-落地" aria-label="Permalink to &quot;2. 合成时先解决“落地”&quot;">​</a></h2><p>按<a href="./../start/first-image">第一张图</a>把真实商品放进背景，保持等比缩放。椅脚都接触地面，阴影对应窗光。若椅子像倾倒或地板斜穿椅脚，先换背景透视，不拉伸商品腿。</p><p>尺寸图与场景图分开，准确标注真实宽高深；不要按房间墙面比例估算商品尺寸。需要展示安装或摆放间距时，用实际测量与图层示意。</p><h2 id="_3-房间改造单独处理" tabindex="-1">3. 房间改造单独处理 <a class="header-anchor" href="#_3-房间改造单独处理" aria-label="Permalink to &quot;3. 房间改造单独处理&quot;">​</a></h2><p>真实空间改造需要原空间照片、尺寸与不能改变的墙体/门窗/设施清单。只探索软装时明确保持墙体、门窗和通道。新家具、材料和灯光方案标设计概念，实际施工另核。</p><p>完整场景生成与局部修改词可由<a href="./../prompts/P01">P01</a>和<a href="./../prompts/P06">P06</a>改写。本节未生成椅子场景或空间方案。</p>`,11)])])}const u=e(r,[["render",o]]);export{_ as __pageData,u as default};
